social=[dict(campaign='news',key='eu',topic='eu-india-research-2027',title='想找跨國研究團隊？歐盟與印度合作有新進展',benefit='看懂經費資格，別把科研協議當個人獎學金。',summary='11月6日完成的談判指向Horizon Europe第二支柱，目標2027年初上路，仍待簽署與批准。研究生可追蹤團隊與徵件；是否有職缺、能領多少資助，要看正式公告。',advice='文章說明合作範圍、尚待程序，以及台灣學生可以怎麼查。',section='國際教育新聞',sectionUrl='https://globalednews.com/news/',url=r['newsPrepared'][0]['url'],lines=['跨國科研合作新進展','歐盟 × 印度']),dict(campaign='scholarship',key='master',topic='scholarship-radar-20261109',title='台灣學生國際獎學金雷達',benefit='找補助不用從一堆陌生校名開始。',summary='當日新增Reading三項學費補助，先比較學位、資格與時程。',advice='全庫總量須部署後核對，不能當成全部仍開放。',section='台灣學生國際獎學金雷達',sectionUrl='https://globalednews.com/scholarships/',url='https://globalednews.com/scholarships/',lines=['台灣學生國際獎學金雷達','免費查詢・公益資訊']),dict(campaign='study-abroad',key='diy',topic='swinburne-wil-placement',title='想累積澳洲職場經驗？先分清專案與實習',benefit='選校要看自己能做什麼，也要看職位怎麼取得。',summary='Swinburne電腦科學Professional課程列六個產業連結專案與12個月有薪實習機會；校方FAQ同時提醒，實習職位須競爭申請，不能保證每位合資格學生取得。',advice='用留學DIY導航比較學校，再查正式課程與當年條件。',section='留學DIY導航',sectionUrl='https://globalednews.com/study-abroad/',url=r['studyAbroadPrepared']['url'],lines=['澳洲實務選校','專案、實習要分清']),dict(campaign='taiwan-universities',key='taiwan',topic='ncku-orchid-science-visit',title='認識大學，不只看榜單：從成大蘭展看研究與生活',benefit='對植物、育種與科普有興趣，可以先記下真正展期。',summary='成大圖書館公告：11月9–10日為佈展，11月12日開幕，蘭花展為11月12–15日，16日撤展。想安排參觀，別把整段場佈期間都當成開展。',advice='國內大學資料庫可再比較學校與科系；出發前查主辦最新公告及入館規則。',section='國內大學資料庫',sectionUrl='https://globalednews.com/taiwan-universities/',url='https://globalednews.com/taiwan-universities/',lines=['從校園活動認識大學','成大蘭展 11/12–15'],sourceUrl=ncku)]
